    p=argparse.ArgumentParser();p.add_argument('--core-formal',type=Path,required=True);p.add_argument('--core-external',type=Path,required=True);p.add_argument('--core-2026',type=Path,required=True);p.add_argument('--classifier-formal',type=Path,required=True);p.add_argument('--classifier-external',type=Path,required=True);p.add_argument('--classifier-2026',type=Path,required=True);p.add_argument('--e2e',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False)
